function sortEvenOdd(nums) {
  const evens = [];
  const odds = [];
  for (let i = 0; i < nums.length; i++) {
    if (i % 2 === 0) {
      evens.push(nums[i]);
    } else {
      odds.push(nums[i]);
    }
  }
  evens.sort((a, b) => a - b);
  odds.sort((a, b) => b - a);
  const result = [];
  for (let i = 0; i < nums.length; i++) {
    if (i % 2 === 0) {
      result.push(evens[i / 2]);
    } else {
      result.push(odds[(i - 1) / 2]);
    }
  }
  return result;
}

