function sortEvenOdd(nums) {
  // Exchange sort that only ever swaps two positions of the same parity.
  const out = nums.slice();
  for (let i = 0; i < out.length; i++) {
    for (let j = i + 2; j < out.length; j += 2) {
      const wrong = i % 2 === 0 ? out[j] < out[i] : out[j] > out[i];
      if (wrong) {
        const t = out[i];
        out[i] = out[j];
        out[j] = t;
      }
    }
  }
  return out;
}

